DOMAIN14 = [{'num': 14, 'topic': 14, 'title': 'Investigate retransmission and zero window', 'objective': 'LO4', 'desc': 'Sequence numbers count bytes; ACK numbers indicate the next expected byte.', 'build': 'Evidence CSV and packet findings', 'services': 'Wireshark, TShark, Python', 'steps': [('Prepare your lab workspace. Open this lab folder in a terminal. Windows uses py -3 in place of python3. Wireshark GUI alone is sufficient for the investigation; CLI scripts require TShark on PATH. Run the fixture verification first.', 'python3 scripts/verify.py'), ('Open data/branch-office.pcap. Apply tcp.stream == 3. Open Analyze > Expert Information and note the repeated server segment.', ''), ('Apply tcp.analysis.retransmission and expand TCP. Compare the same sequence range and payload in the earlier segment; the repeat occurs 1.000 second later.', ''), ('Apply tcp.window_size_value == 0. Confirm the client ACK advertises zero receive window in stream 3. Examine the SYN options: window scaling is negotiated, but zero remains zero.', ''), ('Apply tcp.flags.reset == 1. Identify the port 81 refusal. Complete assets/tcp-evidence.csv with stream, frame, flag/analysis, measured interval and a limitation. Discuss SACK, fast recovery and out-of-order evidence without claiming those events occur in this fixture.', ''), ('Export a reproducible packet table. Record the filter, frame numbers, measurement, explanation and limitation in outputs/findings.md.', 'python3 scripts/export_evidence.py')], 'test': 'The supplied tcp.analysis.retransmission expression matches 1 frame(s) in the specified capture. Run scripts/verify.py and compare the listed frame numbers. Keep your findings and exported table in outputs/. Explain the observed result rather than only copying a count.', 'troubleshooting': 'TShark not found: install Wireshark CLI tools and add the installation folder to PATH; on Windows use the Wireshark install directory. A filter returns zero: clear other filters, use the specified capture, and check the expression is in the display toolbar. TLS remains opaque: select the matching lab-tls.keys file by absolute path, reload, and remove a key-log preference from another lab.', 'reflection': 'Which second observation point would strengthen your conclusion?', 'challenge': 'Develop and explain an alternative filter.', 'duration': 45}]
